// ===== Shell Wrapper =====

struct mavsdk_shell_wrapper {
    std::shared_ptr<mavsdk::Shell> cpp_plugin;
    std::mutex handles_mutex;
    std::vector<mavsdk::Shell::ReceiveHandle*> receive_handles;
};

mavsdk_shell_t
mavsdk_shell_create(mavsdk_system_t system) {
    if (system == nullptr) {
        return nullptr;
    }

    auto wrapper = new mavsdk_shell_wrapper();
    auto system_ptr = reinterpret_cast<std::shared_ptr<mavsdk::System>*>(system);
    wrapper->cpp_plugin = std::make_shared<mavsdk::Shell>(*system_ptr);

    return reinterpret_cast<mavsdk_shell_t>(wrapper);
}

void mavsdk_shell_destroy(mavsdk_shell_t shell) {
    if (shell == nullptr) {
        return;
    }

    auto wrapper = reinterpret_cast<mavsdk_shell_wrapper*>(shell);

    // Unsubscribe all active streams before destroying to prevent
    // callbacks firing into a destroyed object
    {
        std::lock_guard<std::mutex> lock(wrapper->handles_mutex);
        for (auto* h : wrapper->receive_handles) {
            wrapper->cpp_plugin->unsubscribe_receive(std::move(*h));
            delete h;
        }
        wrapper->receive_handles.clear();
    }

    delete wrapper;
}

// ===== Method Implementations =====


// Send sync
mavsdk_shell_result_t
mavsdk_shell_send(
    mavsdk_shell_t shell,
    char* command,
    mavsdk_shell__t device)
{
    auto wrapper = reinterpret_cast<mavsdk_shell_wrapper*>(shell);

    auto ret_value = wrapper->cpp_plugin->send(        command,        translate__from_c(device));

    return translate_result(ret_value);
}

// Receive async
mavsdk_shell_receive_handle_t mavsdk_shell_subscribe_receive(
    mavsdk_shell_t shell,
    mavsdk_shell_receive_callback_t callback,
    void* user_data)
{
    auto wrapper = reinterpret_cast<mavsdk_shell_wrapper*>(shell);

    auto cpp_handle =    wrapper->cpp_plugin->subscribe_receive(
        [callback, user_data](
            mavsdk::Shell:: value) {
                if (callback) {
                    callback(
                        translate__to_c(value),
                        user_data);
                }
        });

    auto cpp_handle_ptr = new mavsdk::Shell::ReceiveHandle(std::move(cpp_handle));

    {
        std::lock_guard<std::mutex> lock(wrapper->handles_mutex);
        wrapper->receive_handles.push_back(cpp_handle_ptr);
    }

    return reinterpret_cast<mavsdk_shell_receive_handle_t>(cpp_handle_ptr);
}

void mavsdk_shell_unsubscribe_receive(
    mavsdk_shell_t shell,
    mavsdk_shell_receive_handle_t handle)
{
    if (handle) {
        auto wrapper = reinterpret_cast<mavsdk_shell_wrapper*>(shell);
        auto cpp_handle = reinterpret_cast<mavsdk::Shell::ReceiveHandle*>(handle);

        {
            std::lock_guard<std::mutex> lock(wrapper->handles_mutex);
            auto& vec = wrapper->receive_handles;
            vec.erase(std::remove(vec.begin(), vec.end(), cpp_handle), vec.end());
        }

        wrapper->cpp_plugin->unsubscribe_receive(std::move(*cpp_handle));
        delete cpp_handle;
    }
}

